+'<span class="k">Returned</span><span class="mono" id="vret">'+(S.rc?n0(dyd())+' yd, '+DY+' rolls':'Not yet')+'</span><span class="k">Variance</span><span class="mono" id="vvar">'+(S.rc?'−'+(gyd()-dyd())+' yd, '+((gyd()-dyd())*100/gyd()).toFixed(1)+'%':'Open')+'</span></div>';
